import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易要義卷三 * 下","description":"周易要義 - 周易要義卷三 * 下","frontmatter":{"title":"周易要義卷三 * 下","description":"周易要義 - 周易要義卷三 * 下"},"headers":[],"relativePath":"classics/yaoyi/008.md","filePath":"classics/yaoyi/008.md"}'),r={name:"classics/yaoyi/008.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易要義卷三-下" tabindex="-1">周易要義卷三 * 下 <a class="header-anchor" href="#周易要義卷三-下" aria-label="Permalink to “周易要義卷三 * 下”">​</a></h1><p>欽定四庫全書</p><p>宋魏了翁輯大畜至離</p><p>䷙</p><p>乾下艮上 大畜：利貞。不家食，吉。利涉大川。正義曰：謂之「大畜」者，乾剛上進，艮止在上，止而畜之，能畜止剛健，故曰「大畜」。彖雲「能止健，大正」也，是能止健，故為「大畜」也。小畜則巽在乾上，以其巽順，不能畜止乾之剛，故云小畜也。此則艮能止之，故為「大畜」也。「利貞」者，人能止健，非正不可，故「利貞」也。「不家食，吉」者，己有大畜之資，當須養贍賢人，不使賢人在家自食，如此乃吉也。「利涉大川」者，豐財養賢，應於天道，不憂險難，故「利涉大川」。畜，本又作蓄，敕六反，義與小畜同。艮宮二世卦。</p><p>彖曰：大畜，剛健篤實，煇光日新其德。凡物既厭而退者，弱也；既榮而隕者，薄也。夫能「煇光日新其德」，唯「剛健篤實」也。</p><p>「大畜剛健」絕句，「篤實煇光」絕句。煇音輝。「日新其德」，鄭以「日新」絕句，「其德」連下句。正義曰：言「大畜剛健篤實」者，此釋大畜之義。「剛健」謂乾也，乾體剛性健，故言「剛健」也。「篤實」謂艮也，艮體靜止，故稱「篤實」也。煇光日新其德者，以其剛健篤實之故，故能輝耀光榮，日日增新其德。</p><p>象曰：天在山中，大畜。君子以多識前言往行，以畜其德。物之可畜於懷，令德不散，盡於此也。正義曰：「天在山中」者，欲取德積於身中，故云「天在山中」。</p><p>九三：良馬逐，利艱貞。曰閒輿衛，利有攸往。凡物極則反，故畜極則通。初、二之進，值於畜盛，故不可以升。至於九三，升於上九，而上九處天衢之亨，塗徑大通，進無違距，可以馳騁，故曰「良馬逐」也。履當其位，進得其時，在乎通路，不憂險阨，故「利艱貞」也。閒，閡也。衛，護也。進得其時，雖涉艱難而無患也。輿雖遇閒而故衛也。與上合志，故「利有攸往」也。逐，如字，鄭本作「逐逐」，雲：「兩馬走也。」姚雲：「逐逐，疾並驅之貌。」一音胄。曰，音越，劉雲：「曰猶言也。」鄭人寔反，雲日習車徒。</p><p>上九：何天之衢，亨。處畜之極，畜極則通，大畜以至於大亨之時。何，辭也，猶云何畜乃天之衢，亨也。何，音河，梁武帝音賀。</p><p>䷚</p><p>震下艮上 頤。貞吉。觀頤，自求口實。正義曰：「頤，貞吉」者，於頤養之世，養此貞正，則得吉也。「觀頤」者，頤，養也，觀此聖人所養物也。「自求口實」者，觀其自養，求其口中之實也。頤以之反養也。此篆文字也。巽宮遊魂卦。</p><p>象曰：山下至飲食。正義曰：山止於上，雷動於下。頤之為用，下動上止，故曰「山下有雷」。頤，人之開發言語，咀嚼飲食，皆動頤之事，故君子觀此頤象，以謹慎言語，裁節飲食。先儒雲：禍從口出，患從口入，故於頤養而慎節也。</p><p>初九，舍爾靈龜，觀我朵頤，兇。朵頤者，嚼也。以陽處下而為動始，不能令物由己養動而求養者也。夫安身莫若不競，修己莫若自保。守道則福至，求祿則辱來。居養賢之世，不能貞其所履，以全其德，而舍其靈龜之明兆，羨我朵頤而躁求，離其致養之至道，𬮭我寵祿而競進，兇莫甚焉。象曰：觀我朵頤，亦不足貴也。正義曰：「朵頤者，嚼也」者，朵是動義，如手之捉物謂之朵也。今動其頤，故知嚼也。「不能令物由已養」者，若道德弘大，則已能養物，是物由已養。今身處無位之地，又居震動之始，是動而自求養也。</p><p>六二，顛頤，拂經於丘頤，徵兇。養下曰顛。拂，違也。經猶義也。丘，所履之常也。處下體之中，無應於上，反而養初，居下不奉上而反養下，故曰「顛頤，拂經於丘」也。以此而養，未見其福也；以此而行，未見有與，故曰「頤，徵兇」。</p><p>六四，顛頤，吉。虎視耽耽，其欲逐逐，無咎。頤屬上體，居得其位，而應於初，以上養下，得頤之義，故曰「顛頤，吉」也。下交不可以瀆，故虎視耽耽，威而不猛，不惡而嚴，養德施賢，何可有利？故其欲逐逐，尚敦實也。修此二者，然後乃得全其吉而「無咎」。觀其自養則履正，察其所養則養陽，頤爻之貴，斯為盛矣。視，徐市志反，又常止反。眈，丁南反，威而不猛也。馬雲：虎下視貌。</p><p>上九，由頤至有慶也。正義曰：「由頤」者，以陽處上而履四陰，陰不能獨為其主，必宗事於陽也。眾陰莫不由之以得其養，故曰「由頤」也。「厲，吉」者，為眾陰之主，不可褻瀆，嚴厲乃吉。</p><p>䷛</p><p>巽下兌上 大過，音相過之過，徐並古臥反，罪過也，超過也。王肅音戈，震宮遊魂卦。</p><p>正義曰：「過」謂過越之過，非經過之過。此衰難之世，唯陽爻乃大能過越常理，以拯患難也，故曰「大過」。以人事言之，猶若聖人過越常理，以拯患難也。「棟橈」者，謂屋棟也。本之與末俱橈弱，以言衰亂之世，始終皆弱也。「利有攸往，亨」者，既遭衰難，聖人利有所往以拯患難，乃得亨通。</p><p>象曰：澤滅至無悶。正義曰：「澤滅木」者，澤體處下，木體處上，澤無滅木之理。今雲「澤滅木」者，乃是澤之甚極而至滅木，是極大過越之義。其大過之卦有二義也：一者物之自然大相過越常分，即此「澤滅木」是也；二者大人大過越常分以拯患難，則九二「枯楊生稊，老夫得其女妻」是也。「君子以獨立不懼，遁世無悶」者，明君子於衰難之時，卓爾獨立，不有畏懼，隱遁於世而無憂悶，欲有遁難之心，其操不改。凡人遇此則不能然，唯君子獨能如此，是其過越之義。遁，本又作遁。</p><p>以陽處陰，能過其本而救其弱者也。上無其應，心無特吝，處過以此，無衰不濟也。故能令枯楊更生稊，老夫更得少妻，拯弱興衰，莫盛斯爻，故「無不利」也。老過則枯，少過則稚。以老分少，則稚者長；以稚分老，則枯者榮。過以相與之謂也。大過至衰而已至壯，以至壯輔至衰，應斯義也。</p><p>九四，棟隆至乎下也。正義曰：「棟隆，吉」者，體居上體，以陽處陰，能拯救其弱，不為下所橈，故得棟隆起而𫉬吉也。「有它吝」者，以有應在初，心不弘闊，故「有它吝」也。象曰：「棟隆」之吉，不橈乎下也者，釋「棟隆之吉」。以其能拯於難，不被橈乎在下，故得「棟隆，吉」。九四應初，行又謙順，能拯於難，然唯只拯初，初謂下也。下得其拯，猶若所居屋棟隆起，下必不橈弱，何得雲「不被橈乎在下」？但經文雲「棟橈」，彖釋「棟橈」者，本末弱也。以屋棟橈弱而偏，則屋下榱柱亦先弱。柱為本，榱為末，觀此彖辭，是已見其義。故子產雲：「棟折榱崩，僑將壓焉。」以屋棟橈折，則榱柱亦同崩，則此義也。</p><p>上六，過涉滅頂，兇，無咎。處大過之極，過之甚也。涉難過甚，故至於滅頂，兇。志在救時，故不可咎也。頂，徐都冷反。象曰：「過涉」之兇，不可咎也。雖兇無咎，不害義也。正義曰：猶龍逢、比干憂時危亂，不懼誅殺，直言深諫，以忤無道之主，遂至滅亡。其意則善而功不成，復有何咎責。</p><p>䷜</p><p>坎下坎上， 習坎。坎，險陷之名也。習謂便習之習。便，習也，重也。劉雲：「水流行不休，故曰習坎。」徐苦感反，本亦作掐。京、劉作「欿」。險也，陷也。八純卦，象水陷陷沒之陷。便，婢面反，通見後。</p><p>有孚，維心亨。剛正在內，「有孚」者也。陽不外發，而在乎內，「心亨」者也。行有尚。內亨外暗，內剛外順，以此行險，「行有尚」也。正義曰：心亨，言心得通也。「行有尚」者，內亨外暗，內剛外柔，以此行險，事事可上，故云「行有尚」也。案：諸卦之名，皆於卦上不加其字。此坎卦之名特加「習」者，以坎為險難，故特加「習」名。「習」有二義：一者，習，重也，謂上下俱坎，是重疊有險，險之重疊，乃成險之用也。二者，人之行險，先須便習其事，乃可得通。</p><p>六三來之坎坎，險且枕，入於坎窞，勿用。既履非其位，而又處兩坎之間，出則之坎，居則亦坎，故曰「來之坎坎」也。枕者，枕枝而不安之謂也，出則無之，處則無安，故曰「險且枕」也。來之皆坎，無所用之，徒勞而已。險且，如字，古文及鄭、向本作檢，鄭雲：「木在手曰檢。」枕，徐針鴆反，王肅針甚反，鄭玄雲：「木在首曰枕。」</p><p>六四樽酒簋貳用缶，納約自牖，終無咎。處重險而履正，以柔居柔，履得其位，以承於五，五亦得位，剛柔各得其所，不相犯位，皆無餘應以相承比，明信顯著，不存外飾。處坎以斯，雖復一樽之酒，二簋之食，瓦缶之器，納此至約，自進於牖，乃可羞之於王公，薦之於宗廟，故「終無咎」也。樽酒，音尊，絕句。簋貳音軌，絕句。用缶，方有反，絕句。舊讀「樽酒簋」絕句，「貳用缶」一句。象曰：「樽酒簋貳」，剛柔際也。剛柔相比而相親焉，際之謂也。正義曰：所以一樽之酒，貳簋之食得進獻者，以六四之柔與九五之剛，兩相交際而相親，故得以此儉約而為禮也。</p><p>九五，坎不盈，祗既平，無咎。為坎之主，而無應輔可以自佐，未能盈坎者也。坎之不盈，則險不盡矣。祗，辭也。為坎之主，盡平乃無咎，故曰「祗既平，無咎」也。說既平，乃無咎，明九五未免於咎也。祗，音支，又祁支反。鄭雲：「當為坻，小丘也。」</p><p>䷝</p><p>離下離上 離利貞，亨。離之為卦，以柔為正，故必貞而後乃亨，故曰「利貞，亨」也。畜牝牛，吉。柔處於內而履正中，牝之善也。外強而內順，牛之善也。離之為體，以柔順為主者也，故不可以畜剛猛之物，而「吉」於「畜牝牛」也。</p><p>正義曰：「柔處於內而履正中，牝之善也」者，若柔不處於內，似婦人而預外事；若柔而不履正中，則邪僻之行，皆非牝之善也。</p><p>又總釋「畜牝牛吉」也。「柔麗於中正」，謂六五、六二之柔皆麗於中，中則不偏，故云中正。以中正為德，故萬事亨。以中正得通，故畜養牝牛而得吉也，以牝牛有中正故也。案：諸卦之彖釋卦名之下，乃釋卦下之義，於後乃嘆而美之。此彖既釋卦名，即廣嘆為卦之美，乃釋卦下之義。與諸卦不例者，此乃夫子隨義則言，因文之便。此既釋離名麗，因廣說日月草木所麗之事，然後卻明卦下之義，更無義例。</p><p>象曰：明兩，至於四方。正義曰：「明兩作，離」者，離為日，日為明，今有上下二離，故云「明兩作，離」也。案：八純之卦，論象不同，各因卦體事義隨文而發。乾坤不論上下之體，直總雲「天行健」，「地𫝑坤」，以天地之大，故總稱上下二體也。雷是連續之至，水為流注不已，義皆取連續相因，故震雲「瀳雷」，坎雲「瀳至」也；風是搖動相隨之物，故云「隨風，巽」也。山澤各自為體，非相入之物，故云「兼山，艮」、麗澤，兌，是兩物各行也。今明之為體，前後各照，故云「明兩作離」，是積聚兩明，乃作於離。若一明暫絕，其離未久，必聚兩明，前後相續，乃得作離卦之美，故云「大人以繼明照於四方」，是繼續其明，乃得照於四方。若明不繼續，則不得久為照臨，所以特雲「明兩作離」，取不絕之義也。作，鄭雲：「作，起也。」荀雲：「用也。」</p><p>六二：黃離，元吉。居中得位，以柔處柔，履文明之盛，而得其中，故曰「黃離，元吉」也。正義曰：黃者，中色也。離者，文明。居中得位，而處於文明，故「元吉」也。故象雲「得中道」，以其得中央黃色之道也。</p><p>六五：出涕沱若、戚嗟若，吉。履非其位，不勝所履，以柔乘剛，不能制下，下剛而進，將來害己，憂傷之深，至於沱嗟也。然所麗在尊，四為逆首，憂傷至深，眾之所助，故乃沱嗟而𫉬吉也。出，如字，徐尺遂反，王嗣宗勑類反。</p><p>正義：象曰「六五之吉，離王公」者，此釋六五「吉」義也。所以終得吉者，以其所居在五，離附於王公之位，被眾所助，故得吉也。五為王位，而言公者，此連王而言公，取其便文以會韻也。離王公，音麗，鄭作麗。王肅雲：「麗，王者之後為公。」梁武力智反。周易要義卷三下</p>',38)])])}const f=a(r,[["render",i]]);export{m as __pageData,f as default};
